    relatorio += "❌ Nenhum registro de preço ou auditoria encontrado para este produto.";
} else {
    // Varre os resultados encontrados
    for (let item of lista) {
        // Formata a data de criação do registro, porque a do banco de dados é muito feia
        const dataFormatada = new Date(item.criado_em).toLocaleString('pt-BR', {dateStyle: 'short', timeStyle: 'short'});

