// Puxa o comando lá do primeiro nó
const dadosIniciais = $('Code in JavaScript').first().json;
const texto = dadosIniciais.comando || "";

// Remove a palavra "inserir " do começo
let restoDaFrase = texto.replace(/^inserir\s+/i, '').trim();

// Tenta encontrar o preço no final da frase (ex: 8.50, 8,50, 15)
// Essa regex procura a última sequência de números (com ponto ou vírgula) na string
const regexPreco = /[\d.,]+$/;
const matchPreco = restoDaFrase.match(regexPreco);

let precoLimpo = 0;
let produtoLimpo = restoDaFrase;

if (matchPreco) {
    // Substitui vírgula por ponto para o banco de dados não reclamar e converte para decimal
    precoLimpo = parseFloat(matchPreco[0].replace(',', '.'));

    // Corta o preço do texto para sobrar só o nome do produto
    produtoLimpo = restoDaFrase.substring(0, matchPreco.index).trim();

    // Se sobrar um "r$" ou traço no final do produto, ele limpa
    produtoLimpo = produtoLimpo.replace(/(r\$|-)$/i, '').trim();
}

return {
    json: {
        chatId: dadosIniciais.chatId,
        texto_original: texto,
        produto_manual: produtoLimpo,
        preco_manual: precoLimpo
    }
};

